/* Leitbild-specific prose styling — used by <Prose variant="leitbild"> */
.prose.leitbild {
  --tw-prose-body: var(--color-gray-600);
  --tw-prose-headings: var(--color-gray-900);
  --tw-prose-bold: var(--color-gray-900);
  --tw-prose-quotes: var(--color-gray-600);
  --tw-prose-bullets: var(--color-primary);
  --tw-prose-hr: var(--color-gray-100);
}

.dark .prose.leitbild {
  --tw-prose-body: var(--color-gray-300);
  --tw-prose-headings: var(--color-white);
  --tw-prose-bold: var(--color-white);
  --tw-prose-quotes: var(--color-gray-300);
  --tw-prose-bullets: var(--color-primary);
  --tw-prose-hr: var(--color-gray-800);
}

.prose.leitbild h1 {
  color: var(--color-primary);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  margin-top: 0;
  margin-bottom: 2rem;
}

.prose.leitbild h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-top: 0;
  margin-bottom: 0.5rem;
  color: var(--color-gray-900);
}

.dark .prose.leitbild h2 {
  color: var(--color-white);
}

.prose.leitbild p {
  margin-top: 0.5rem;
  margin-bottom: 0;
  line-height: 1.7;
  text-align: left;
}

.prose.leitbild hr {
  border: 0;
  margin-top: 2rem;
  margin-bottom: 2rem;
  border-top: 1px solid var(--tw-prose-hr);
}

.prose.leitbild ul {
  margin-top: 0.75rem;
  padding-left: 0;
  list-style: none;
}

.prose.leitbild ul li {
  position: relative;
  padding-left: 1.25rem;
  margin-top: 0.5rem;
}

.prose.leitbild ul li::before {
  content: '•';
  position: absolute;
  left: 0;
  color: var(--color-primary);
  font-weight: 700;
}

